using Microsoft.SqlServer.TransactSql.ScriptDom;
namespace Seamless.Database.Query;
internal sealed partial class QueryBinder{
    internal sealed class RoutineBinding(SqlParameter[]parameters,SqlType returnType){internal SqlParameter[]Parameters{get;}=parameters;internal SqlType ReturnType{get;}=returnType;internal Func<EvalFrame,(bool Returned,object?Value)>Body{get;set;}=_=>throw new InvalidOperationException("The recursive routine has not finished binding.");internal bool Computed{get;set;}internal bool NullOnNullInput{get;set;}internal BoundScalar?ReturnedScalar{get;set;}internal int DirectParameter{get;set;}=-1;}
    private BoundScalar BindRoutineInvocation(RoutineBinding binding,IList<ScalarExpression>arguments,IReadOnlyList<BindingColumn>columns,IReadOnlyList<BindingColumn>outer,List<AggregateBinding>?aggregates){
        var values=arguments.Select(argument=>this.BindScalar(argument,columns,outer,aggregates)).ToArray();var computed=binding.Computed;if(binding.DirectParameter>=0&&binding.ReturnedScalar is{} returned){var index=binding.DirectParameter;computed=FloatingConversion(binding.ReturnType,returned with{IsComputedFloatingPoint=FloatingConversion(binding.Parameters[index].Type,values[index])});}return new(binding.ReturnType,true,frame=>{frame.Execution.Scope.ThrowIfUnavailable();if(frame.Execution.RoutineDepth>=32){throw new SqlQueryException("Maximum stored procedure, function, trigger, or view nesting level exceeded (limit 32).",217);}var variables=new Dictionary<string,object?>(StringComparer.OrdinalIgnoreCase);for(var index=0;index<binding.Parameters.Length;index++){var value=SqlValues.ConvertTo(values[index].Value(frame),binding.Parameters[index].Type,true);if(value is null&&binding.NullOnNullInput){return null;}variables.Add(binding.Parameters[index].Name,value);}return SqlValues.ConvertTo(binding.Body(new([],null,new(frame.Execution.Scope,variables,frame.Execution.Options,frame.Execution.RoutineDepth+1,frame.Execution.Timestamp))).Value,binding.ReturnType,true);}){IsComputedFloatingPoint=computed};
    }
    private int routineLoopDepth;
    private enum RoutineLoopControl{Break,Continue}
    private Func<EvalFrame,(bool Returned,object?Value)>BindRoutineStatements(IList<TSqlStatement>statements){
        var actions=statements.Select(this.BindRoutineStatement).ToArray();
        return frame=>{foreach(var action in actions){frame.Execution.Scope.ThrowIfUnavailable();var result=action(frame);if(result.Returned){return result;}}return(false,null);};
    }
    private Func<EvalFrame,(bool Returned,object?Value)>BindRoutineStatement(TSqlStatement statement){
        switch(statement){
            case ReturnStatement returned:{var value=this.BindScalar(returned.Expression,[],[],null);return frame=>(true,value.Value(frame));}
            case BeginEndBlockStatement block:return this.BindRoutineStatements(block.StatementList.Statements);
            case DeclareVariableStatement declaration:{var initializers=declaration.Declarations.Select(x=>(Name:x.VariableName.Value,Type:BindType(x.DataType),Value:BindInitializer(x.Value))).ToArray();return frame=>{var variables=(IDictionary<string,object?>)frame.Execution.Parameters;foreach(var initializer in initializers){variables[initializer.Name]=SqlValues.ConvertTo(initializer.Value?.Value(frame),initializer.Type,true);}return(false,null);};}
            case SetVariableStatement assignment:{if(assignment.AssignmentKind!=AssignmentKind.Equals||assignment.FunctionCallExists){throw Unsupported(assignment);}var parameter=this.parameters.FirstOrDefault(x=>Equal(x.Name,assignment.Variable.Name))??throw new SqlQueryException("Unknown routine local "+assignment.Variable.Name,137);var value=this.BindScalar(assignment.Expression,[],[],null);return frame=>{((IDictionary<string,object?>)frame.Execution.Parameters)[parameter.Name]=SqlValues.ConvertTo(value.Value(frame),parameter.Type,true);return(false,null);};}
            case IfStatement conditional:{var predicate=this.BindBoolean(conditional.Predicate,[],[],null);var yes=this.BindRoutineStatement(conditional.ThenStatement);Func<EvalFrame,(bool Returned,object?Value)>no=_=>(false,null);if(conditional.ElseStatement is not null){no=this.BindRoutineStatement(conditional.ElseStatement);}return frame=>{if(predicate(frame)==true){return yes(frame);}return no(frame);};}
            case WhileStatement loop:{var predicate=this.BindBoolean(loop.Predicate,[],[],null);Func<EvalFrame,(bool Returned,object?Value)>body;this.routineLoopDepth++;try{body=this.BindRoutineStatement(loop.Statement);}finally{this.routineLoopDepth--;}return frame=>{while(predicate(frame)==true){frame.Execution.Scope.ThrowIfUnavailable();var result=body(frame);if(result.Value is RoutineLoopControl signal){if(signal==RoutineLoopControl.Break){break;}continue;}if(result.Returned){return result;}}return(false,null);};}
            case BreakStatement:{if(this.routineLoopDepth==0){throw new SqlQueryException("BREAK is outside a WHILE loop.",135);}return _=>(true,RoutineLoopControl.Break);}
            case ContinueStatement:{if(this.routineLoopDepth==0){throw new SqlQueryException("CONTINUE is outside a WHILE loop.",136);}return _=>(true,RoutineLoopControl.Continue);}
            case SelectStatement select when select.QueryExpression is QuerySpecification query&&query.SelectElements.Count>0&&query.SelectElements.All(static element=>element is SelectSetVariable):{
                var assignments=query.SelectElements.Cast<SelectSetVariable>().ToArray();var targets=assignments.Select(assignment=>{if(assignment.AssignmentKind!=AssignmentKind.Equals){throw Unsupported(assignment);}return this.parameters.FirstOrDefault(parameter=>Equal(parameter.Name,assignment.Variable.Name))??throw new SqlQueryException("Unknown routine local "+assignment.Variable.Name,137);}).ToArray();BoundQuery bound;
                query.SelectElements.Clear();try{foreach(var assignment in assignments){query.SelectElements.Add(new SelectScalarExpression{Expression=assignment.Expression});}bound=this.BindStatement(select);}finally{query.SelectElements.Clear();foreach(var assignment in assignments){query.SelectElements.Add(assignment);}}
                return frame=>{var variables=(IDictionary<string,object?>)frame.Execution.Parameters;foreach(var row in bound.Rows(frame.Execution,frame.Outer)){frame.Execution.Scope.ThrowIfUnavailable();for(var index=0;index<targets.Length;index++){variables[targets[index].Name]=SqlValues.ConvertTo(row[index],targets[index].Type,true);}}return(false,null);};
            }
            default:throw Unsupported(statement);
        }
    }
    private static ScalarExpression?SingleRoutineReturn(IList<TSqlStatement>statements){if(statements.Count!=1){return null;}if(statements[0] is BeginEndBlockStatement block){return SingleRoutineReturn(block.StatementList.Statements);}if(statements[0] is ReturnStatement returned){return returned.Expression;}return null;}
    private BoundScalar?BindInitializer(ScalarExpression?expression){if(expression is null){return null;}return this.BindScalar(expression,[],[],null);}
    private static IEnumerable<SqlParameter>RoutineLocals(TSqlFragment fragment){
        if(fragment is DeclareVariableElement variable){yield return new(variable.VariableName.Value,BindType(variable.DataType));yield break;}
        foreach(var property in fragment.GetType().GetProperties()){if(property.Name=="ScriptTokenStream"||property.GetIndexParameters().Length!=0){continue;}if(property.GetValue(fragment) is TSqlFragment child){foreach(var parameter in RoutineLocals(child)){yield return parameter;}}else if(property.GetValue(fragment) is global::System.Collections.IEnumerable items){foreach(var item in items){if(item is TSqlFragment descendant){foreach(var parameter in RoutineLocals(descendant)){yield return parameter;}}}}}
    }
}

